window.products.push({"id":424098,"name":"Fred Perry Men's Hallam Printed Canvas Fashion Sneaker","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81c3f5efSSL._AC_UL1500_.jpg","description":"Three-time Wimbledon and Davis Cup winner Fred Perry began his illustrious sportswear career in the late 1940s when he was approached to design a sweatband bearing his own name. More than 50 years later, Fred Perry and laurel wreath logo are synonymous with fashion-foward clothing and footwear, both on the court and off.","images":["https://m.media-amazon.com/images/I/81c3f5efSSL._AC_UL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Fred Perry","source_asin":"B00JVDKEIU","category_path":"Home & Kitchen"},"sku":"BM-424098","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00JVDKEIU","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00JVDKEIU","price_pending":true,"merchant_ready":false});
